{{ config(materialized='table') }}
SELECT
    customer_hk,
    customer_id
FROM (
    SELECT
        customer_hk,
        customer_id,
        ROW_NUMBER() OVER (
            PARTITION BY customer_hk
            ORDER BY __source_ordinal
        ) AS __rn
    FROM (
        SELECT DISTINCT
            LOWER(SHA2(UPPER(TRIM(CAST(customer_id AS VARCHAR))), 256)) AS customer_hk,
            UPPER(TRIM(CAST(customer_id AS VARCHAR))) AS customer_id,
            0 AS __source_ordinal
        FROM {{ ref('stg_customers_crm') }}
        WHERE customer_id IS NOT NULL
        UNION ALL
        SELECT DISTINCT
            LOWER(SHA2(UPPER(TRIM(CAST(customer_id AS VARCHAR))), 256)) AS customer_hk,
            UPPER(TRIM(CAST(customer_id AS VARCHAR))) AS customer_id,
            1 AS __source_ordinal
        FROM {{ ref('stg_customers_web') }}
        WHERE customer_id IS NOT NULL
    ) AS combined
) AS ranked
WHERE __rn = 1
